class Solution {
public:
    int countWays(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size(), ans = 0;
        if (nums[0] > 0) ans++;
        if (nums.back() < n) ans++;
        for (int i = 0; i < n - 1; i++) {
            int k = i + 1;
            if (nums[i] < k && nums[i + 1] > k) ans++;
        }
        return ans;
    }
};

class Solution {
    public int countWays(List<Integer> nums) {
        Collections.sort(nums);
        int n = nums.size(), ans = 0;
        if (nums.get(0) > 0) ans++;
        if (nums.get(n - 1) < n) ans++;
        for (int i = 0; i < n - 1; i++) {
            int k = i + 1;
            if (nums.get(i) < k && nums.get(i + 1) > k) ans++;
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
