var countWays = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let ans = 0;
    if (nums[0] > 0) ans++;
    if (nums[n - 1] < n) ans++;
    for (let i = 0; i < n - 1; i++) {
        const k = i + 1;
        if (nums[i] < k && nums[i + 1] > k) ans++;
    }
    return ans;
};
